// Generated by esquadro: do not edit. A page of settings: its sections in a
// menu at the left (at the top on a phone), the one chosen at the right,
// kept in the URL (?section=). A section's content may be a card: inside,
// it loses its frame.
import { useNavigate, useSearch } from "@tanstack/react-router"
import type { LucideIcon } from "lucide-react"
import type { ReactNode } from "react"
import { Card } from "@/components/ui/card"
import { cn } from "@/lib/utils"

/** A section of the settings: its key in the URL, its name and icon, what it shows. */
export interface SettingsSection {
  key: string
  label: string
  icon?: LucideIcon
  content: ReactNode
}

export function Settings({ sections }: { sections: SettingsSection[] }) {
  const search = useSearch({ strict: false }) as { section?: string }
  const navigate = useNavigate()
  const current = sections.find((s) => s.key === search.section) ?? sections[0]
  if (!current) return null
  return (
    <Card className="gap-0 py-0">
      <div className="grid md:grid-cols-[240px_minmax(0,1fr)]">
        <nav className="flex gap-1 overflow-x-auto border-b border-border p-3 md:flex-col md:border-r md:border-b-0 md:p-4" aria-label={current.label}>
          {sections.map((s) => {
            const active = s === current
            return (
              <button
                key={s.key}
                type="button"
                aria-current={active ? "page" : undefined}
                onClick={() => navigate({ to: ".", search: (prev: Record<string, unknown>) => ({ ...prev, section: s.key }) as never, replace: true })}
                className={cn(
                  "flex h-11 shrink-0 items-center gap-3 rounded-lg px-3 text-sm font-semibold whitespace-nowrap text-sidebar-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
                  active && "bg-primary/10 text-primary hover:bg-primary/10 hover:text-primary",
                )}
              >
                {s.icon && <s.icon className="size-[18px]" />}
                {s.label}
              </button>
            )
          })}
        </nav>
        <div className="min-w-0 p-5 md:p-8 [&>[data-slot=card]]:gap-5 [&>[data-slot=card]]:rounded-none [&>[data-slot=card]]:border-0 [&>[data-slot=card]]:bg-transparent [&>[data-slot=card]]:py-0 [&_[data-slot=card-content]]:px-0 [&_[data-slot=card-footer]]:px-0 [&_[data-slot=card-header]]:mb-6 [&_[data-slot=card-header]]:px-0">
          {current.content}
        </div>
      </div>
    </Card>
  )
}
